import Capacitor
import MusicKit
import UIKit

// Apple Music sign-in for the iPhone app.
// The web layer's MusicKit JS sign-in can only post its token back to an
// origin registered on the MusicKit identifier, and capacitor://localhost is
// not one, so inside the app the Apple sheet opened and Allow went nowhere.
// MusicKit for Swift asks for access with the system prompt instead and hands
// back both tokens the Apple Music API needs:
//   - the developer token, generated by MusicKit itself. That needs the
//     MusicKit app service on the App ID; when it is off, the bundled web
//     token (passed in as fallbackDeveloperToken) is used instead, so the
//     plugin still works, just with the bundled token's expiry.
//   - the Music User Token for that developer token.
// The web layer keeps doing every API call itself (search, playlist POST), so
// the matching rules stay in one place.
@objc(AppleMusicPlugin)
public class AppleMusicPlugin: CAPPlugin, CAPBridgedPlugin {
    public let identifier = "AppleMusicPlugin"
    public let jsName = "AppleMusicNative"
    public let pluginMethods: [CAPPluginMethod] = [
        CAPPluginMethod(name: "authorize", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "tokens", returnType: CAPPluginReturnPromise)
    ]

    // Shows the system Apple Music prompt when access has never been asked for.
    @objc func authorize(_ call: CAPPluginCall) {
        let fallback = call.getString("fallbackDeveloperToken")
        Task {
            let status = await MusicAuthorization.request()
            await self.resolveTokens(call, status: status, fallback: fallback)
        }
    }

    // Never prompts. Used on launch and before each API call, so a signed-in
    // user's tokens come back after the app restarts.
    @objc func tokens(_ call: CAPPluginCall) {
        let fallback = call.getString("fallbackDeveloperToken")
        Task {
            await self.resolveTokens(call, status: MusicAuthorization.currentStatus, fallback: fallback)
        }
    }

    private static func statusName(_ status: MusicAuthorization.Status) -> String {
        switch status {
        case .authorized: return "authorized"
        case .denied: return "denied"
        case .restricted: return "restricted"
        case .notDetermined: return "notDetermined"
        @unknown default: return "unknown"
        }
    }

    private func resolveTokens(_ call: CAPPluginCall, status: MusicAuthorization.Status, fallback: String?) async {
        guard status == .authorized else {
            call.resolve(["status": Self.statusName(status)])
            return
        }
        let provider = DefaultMusicTokenProvider()
        let developerToken: String
        var tokenSource = "musickit"
        do {
            developerToken = try await provider.developerToken(options: [])
        } catch {
            guard let fallback = fallback, !fallback.isEmpty else {
                call.reject(String(describing: error), "developer_token_failed", error)
                return
            }
            developerToken = fallback
            tokenSource = "bundled"
        }
        do {
            let userToken = try await provider.userToken(for: developerToken, options: [])
            var result: [String: Any] = [
                "status": "authorized",
                "developerToken": developerToken,
                "userToken": userToken,
                "tokenSource": tokenSource
            ]
            // Creating a library playlist needs a subscription with Sync
            // Library on. Report both so the web layer can say which is off.
            if let subscription = try? await MusicSubscription.current {
                result["canPlayCatalogContent"] = subscription.canPlayCatalogContent
                result["hasCloudLibraryEnabled"] = subscription.hasCloudLibraryEnabled
            }
            call.resolve(result)
        } catch {
            call.reject(String(describing: error), "user_token_failed", error)
        }
    }
}
